BEGIN;
DO $$
DECLARE office uuid:=gen_random_uuid();driver_user uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();customer_user uuid:=gen_random_uuid();driver uuid;other_driver uuid;customer uuid;vehicle uuid;truck uuid;other_truck uuid;shipment uuid;delivery uuid;
 marker text:='routing-test-'||gen_random_uuid();d_version timestamptz;s_version timestamptz;promised timestamptz:=now()+interval '1 day';position_at timestamptz:=now()-interval '10 seconds';payload jsonb;plan jsonb;eta jsonb;context jsonb;original_version uuid;
BEGIN
 INSERT INTO auth.users(id,email,raw_app_meta_data,raw_user_meta_data) VALUES(office,marker||'-office@example.invalid','{}','{}'),(driver_user,marker||'-driver@example.invalid','{}','{}'),(outsider,marker||'-other@example.invalid','{}','{}'),(customer_user,marker||'-customer@example.invalid','{}','{}');
 UPDATE public.users SET role='staff' WHERE id=office;
 UPDATE public.users SET role='driver' WHERE id IN(driver_user,outsider);
 SELECT id INTO customer FROM public.customers WHERE user_id=customer_user;
 INSERT INTO public.drivers(user_id,full_name,license_number) VALUES(driver_user,marker,marker) RETURNING id INTO driver;
 INSERT INTO public.drivers(user_id,full_name,license_number) VALUES(outsider,marker||'-other',marker||'-other') RETURNING id INTO other_driver;
 INSERT INTO public.vehicle_types(name,default_capacity_kg) VALUES(marker,10000) RETURNING id INTO vehicle;
 INSERT INTO public.trucks(plate_number,vehicle_type_id,capacity_kg) VALUES(marker,vehicle,10000) RETURNING id INTO truck;
 INSERT INTO public.trucks(plate_number,vehicle_type_id,capacity_kg) VALUES(marker||'-other',vehicle,10000) RETURNING id INTO other_truck;
 INSERT INTO public.shipments(customer_id,status,pickup_address,dropoff_address,weight_kg,estimated_arrival,quoted_amount) VALUES(customer,'assigned',marker,marker,6000,promised,12000) RETURNING id,updated_at INTO shipment,s_version;
 INSERT INTO public.deliveries(shipment_id,driver_id,truck_id,status,route_started_at) VALUES(shipment,driver,truck,'assigned',now()-interval '2 minutes') RETURNING id,updated_at INTO delivery,d_version;
 payload:=jsonb_build_object('truck_id',truck,'confirmed',true,'reason','Office verified both truck entrances and actual loaded dimensions','pickup_lat',14.6,'pickup_lng',120.96,'dropoff_lat',14.65,'dropoff_lng',120.98,'profile',jsonb_build_object('height',3.5,'width',2.4,'length',10,'weight',20,'axleload',8,'hazmat',false),'geometry','{"type":"FeatureCollection","features":[{"type":"Feature","geometry":{"type":"LineString","coordinates":[[120.96,14.6],[120.98,14.65]]}}]}'::jsonb,'distance_km',10,'duration_minutes',20);
 PERFORM set_config('request.jwt.claim.sub',driver_user::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',driver_user,'role','authenticated')::text,true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 context:=public.delivery_routing_context(delivery);
 IF context->'plan'<>'null'::jsonb OR context->'shipment'->>'pickup_lat' IS NOT NULL THEN RAISE EXCEPTION 'Legacy pins fabricated';END IF;
 BEGIN PERFORM public.store_confirmed_delivery_route(office,delivery,d_version,s_version,payload);RAISE EXCEPTION 'Driver directly persisted provider route';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'RESET ROLE';EXECUTE 'SET LOCAL ROLE service_role';
 BEGIN PERFORM public.store_confirmed_delivery_route(driver_user,delivery,d_version,s_version,payload);RAISE EXCEPTION 'Driver confirmed legacy pins';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.store_confirmed_delivery_route(office,delivery,d_version-interval '1 second',s_version,payload);RAISE EXCEPTION 'Stale route saved';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'ASSIGNMENT_CHANGED_RELOAD' THEN RAISE;END IF;END;
 BEGIN PERFORM public.store_confirmed_delivery_route(office,delivery,d_version,s_version,payload||'{"confirmed":false}');RAISE EXCEPTION 'Unchecked pins saved';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'OFFICE_CONFIRMATION_REQUIRED' THEN RAISE;END IF;END;
 BEGIN PERFORM public.store_confirmed_delivery_route(office,delivery,d_version,s_version,jsonb_set(payload,'{profile,weight}','6'));RAISE EXCEPTION 'Cargo substituted for loaded truck weight';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'INVALID_LOADED_TRUCK_WEIGHT' THEN RAISE;END IF;END;
 plan:=public.store_confirmed_delivery_route(office,delivery,d_version,s_version,payload);original_version:=(plan->>'version')::uuid;
 IF (SELECT estimated_arrival FROM public.shipments WHERE id=shipment) IS DISTINCT FROM promised OR (SELECT quoted_amount FROM public.shipments WHERE id=shipment)<>12000 OR (SELECT route_geometry FROM public.shipments WHERE id=shipment) IS DISTINCT FROM payload->'geometry' THEN RAISE EXCEPTION 'Promises/price/geometry not preserved';END IF;
 INSERT INTO public.tracking_logs(delivery_id,truck_id,driver_id,latitude,longitude,accuracy_m,recorded_at) VALUES(delivery,truck,driver,14.6,120.96,10,position_at);
 eta:=public.store_delivery_route_eta(driver_user,delivery,original_version,'pickup',position_at,600,10000);
 IF eta->>'leg'<>'pickup' OR (eta->>'eta_at')::timestamptz<=(eta->>'calculated_at')::timestamptz OR (eta->>'expires_at')::timestamptz>position_at+interval '2 minutes' THEN RAISE EXCEPTION 'ETA timestamps invalid';END IF;
 BEGIN PERFORM public.store_delivery_route_eta(outsider,delivery,original_version,'pickup',position_at,600,10000);RAISE EXCEPTION 'Other driver wrote ETA';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.store_delivery_route_eta(driver_user,delivery,gen_random_uuid(),'pickup',position_at,600,10000);RAISE EXCEPTION 'Stale route ETA saved';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'ETA_CONTEXT_CHANGED' THEN RAISE;END IF;END;
 EXECUTE 'RESET ROLE';
 UPDATE public.deliveries SET truck_id=other_truck WHERE id=delivery;
 EXECUTE 'SET LOCAL ROLE service_role';
 BEGIN PERFORM public.store_delivery_route_eta(driver_user,delivery,original_version,'pickup',position_at,600,10000);RAISE EXCEPTION 'Changed truck ETA saved';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'ETA_CONTEXT_CHANGED' THEN RAISE;END IF;END;
 EXECUTE 'RESET ROLE';UPDATE public.deliveries SET truck_id=truck,status='in_transit' WHERE id=delivery;
 EXECUTE 'SET LOCAL ROLE service_role';
 BEGIN PERFORM public.store_delivery_route_eta(driver_user,delivery,original_version,'pickup',position_at,600,10000);RAISE EXCEPTION 'Wrong ETA leg saved';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'ETA_CONTEXT_CHANGED' THEN RAISE;END IF;END;
 eta:=public.store_delivery_route_eta(driver_user,delivery,original_version,'destination',position_at,600,10000);
 EXECUTE 'RESET ROLE';
 UPDATE public.tracking_logs SET accuracy_m=500 WHERE delivery_id=delivery;
 EXECUTE 'SET LOCAL ROLE service_role';
 BEGIN PERFORM public.store_delivery_route_eta(driver_user,delivery,original_version,'destination',position_at,600,10000);RAISE EXCEPTION 'Inaccurate ETA saved';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'ETA_CONTEXT_CHANGED' THEN RAISE;END IF;END;
 EXECUTE 'RESET ROLE';
 UPDATE public.tracking_logs SET accuracy_m=10,recorded_at=now()-interval '3 minutes' WHERE delivery_id=delivery;
 EXECUTE 'SET LOCAL ROLE service_role';
 BEGIN PERFORM public.store_delivery_route_eta(driver_user,delivery,original_version,'destination',now()-interval '3 minutes',600,10000);RAISE EXCEPTION 'Stale GPS ETA saved';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'ETA_CONTEXT_CHANGED' THEN RAISE;END IF;END;
 EXECUTE 'RESET ROLE';
 PERFORM set_config('request.jwt.claim.sub',outsider::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',outsider,'role','authenticated')::text,true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 IF EXISTS(SELECT 1 FROM public.delivery_route_plans WHERE delivery_id=delivery) OR EXISTS(SELECT 1 FROM public.delivery_route_eta WHERE delivery_id=delivery) THEN RAISE EXCEPTION 'Other driver route leak';END IF;
 BEGIN PERFORM public.delivery_routing_context(delivery);RAISE EXCEPTION 'Other driver context leak';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'RESET ROLE';
 PERFORM set_config('request.jwt.claim.sub',customer_user::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',customer_user,'role','authenticated')::text,true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 BEGIN PERFORM public.delivery_routing_context(delivery);RAISE EXCEPTION 'Customer context leak';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'RESET ROLE';
 PERFORM set_config('request.jwt.claim.sub',office::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',office,'role','authenticated')::text,true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 IF (public.delivery_routing_context(delivery)->'plan'->>'version')::uuid<>original_version THEN RAISE EXCEPTION 'Office plan unavailable';END IF;
 BEGIN INSERT INTO public.delivery_route_eta(delivery_id) VALUES(delivery);RAISE EXCEPTION 'Office forged ETA directly';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'RESET ROLE';
 PERFORM set_config('request.jwt.claim.sub','',true);PERFORM set_config('request.jwt.claims','{"role":"anon"}',true);
 EXECUTE 'SET LOCAL ROLE anon';
 BEGIN PERFORM public.delivery_routing_context(delivery);RAISE EXCEPTION 'Anon route context';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'RESET ROLE';
END $$;
ROLLBACK;
SELECT 'PASS: explicit office confirmation, legacy preservation, truck/cargo/profile/version checks, saved geometry, unchanged prices/promises, GPS/leg/freshness gates and driver/customer/anon isolation; fixtures rolled back' result;
